import { test, expect, Page } from '@playwright/test';

async function visibleBoxes(page: Page) {
  const out: { name: string; width: number; height: number }[] = [];
  for (const role of ['button', 'link'] as const) {
    const items = page.getByRole(role);
    const count = await items.count();
    for (let i = 0; i < count; i++) {
      const el = items.nth(i);
      // Expo keeps hidden previous screens in DOM - count only visible elements
      if (!(await el.isVisible())) continue;
      const box = await el.boundingBox();
      if (!box || box.width === 0 || box.height === 0) continue;
      const name = (await el.getAttribute('aria-label')) ?? ((await el.innerText()).trim() || role);
      out.push({ name: `${role}:${name}`, width: box.width, height: box.height });
    }
  }
  return out;
}

test.describe('Дизайн-система — типографика, касания, цвета', () => {
  test('Зоны касания на гостевых экранах не меньше 44×44 #22865e77 @iphone @prod-safe', async ({ page }) => {
    // For /welcome, /sign-in, /sign-up, /design collect visible buttons and links
    for (const path of ['/welcome', '/sign-in', '/sign-up', '/design']) {
      await page.goto(`https://banci.expo.app${path}`);
      await page.waitForLoadState('networkidle');
      const boxes = await visibleBoxes(page);
      const small = boxes.filter((b) => b.width < 44 || b.height < 44);
      expect(small, `Small tap targets on ${path}`).toEqual([]);
    }

    // Specific elements must be at least 44x44
    const checks: Array<[string, string, (p: Page) => ReturnType<Page['getByText']>]> = [
      ['/sign-in', 'שכחתי סיסמה?', (p) => p.getByRole('button', { name: 'שכחתי סיסמה?' }).or(p.getByRole('link', { name: 'שכחתי סיסמה?' })).locator('visible=true').first()],
      ['/sign-in', 'הרשמה', (p) => p.getByRole('button', { name: 'הרשמה', exact: true }).or(p.getByRole('link', { name: 'הרשמה', exact: true })).locator('visible=true').first()],
      ['/sign-in', 'כניסה', (p) => p.getByRole('button', { name: 'כניסה' }).locator('visible=true').first()],
      ['/sign-in', 'הצגת הסיסמה', (p) => p.getByLabel('הצגת הסיסמה').locator('visible=true').first()],
      ['/design', 'הכל', (p) => p.getByRole('button', { name: 'הכל', exact: true }).or(p.getByRole('link', { name: 'הכל', exact: true })).locator('visible=true').first()],
    ];
    for (const [path, name, get] of checks) {
      await page.goto(`https://banci.expo.app${path}`);
      await page.waitForLoadState('networkidle');
      const box = await get(page).boundingBox();
      expect(box, name).not.toBeNull();
      expect(box!.width, `${name} width`).toBeGreaterThanOrEqual(44);
      expect(box!.height, `${name} height`).toBeGreaterThanOrEqual(44);
    }
  });
});
